import { readFileSync } from 'node:fs';
const cs = JSON.parse(readFileSync('/workspace/probe/cases/regex-pattern.json', 'utf8'));
console.log('count', cs.length);
for (const [i, c] of cs.entries()) {
  try { JSON.parse(c.a); JSON.parse(c.b); } catch (e) { console.log('BADJSON', i + 1, c.a, c.b); }
}
const seen = new Map();
for (const [i, c] of cs.entries()) {
  const k = c.a + ' ' + c.b;
  if (seen.has(k)) console.log('DUP', seen.get(k), i + 1);
  else seen.set(k, i + 1);
}
for (const tag of ['F9c', 'F28', 'E24', 'F13d', 'E7b', 'D6']) {
  const c = cs.find((x) => x.note.startsWith(tag));
  console.log(tag, JSON.stringify(JSON.parse(c.b).pattern), 'inst=', JSON.stringify(JSON.parse(c.a)));
}

import { readFileSync } from 'node:fs';
const obs = JSON.parse(readFileSync('/workspace/probe/observed/regex-pattern.json', 'utf8'));
const bad = obs.filter((o) => o.code !== 0);
console.log('exit-nonzero count:', bad.length, 'of', obs.length);
for (const o of bad) {
  const sch = JSON.parse(o.b);
  const pat = sch.pattern !== undefined ? JSON.stringify(sch.pattern) : JSON.stringify(o.b);
  const msg = (o.stderrTail || '').split('|').map((s) => s.trim()).filter((s) => /Error|error/.test(s)).join(' ; ');
  console.log(`code=${o.code}  ${pat.padEnd(34)} ${msg}`);
}
const counts = {};
for (const o of obs) {
  const k = o.code === 0 ? 'out ' + JSON.stringify(o.stdout) : 'EXIT ' + o.code;
  counts[k] = (counts[k] || 0) + 1;
}
console.log(counts);
